    def _clean_focus_phase_id(raw) -> str:
        return re.sub(r"[^A-Za-z0-9_.:-]", "", str(raw or ""))[:80]


    @app.route("/api/student/focus/phase/start", methods=["POST"])
    def student_focus_phase_start():
        """Register a focus phase before the browser timer starts."""

        if not _logged_in():
            return jsonify({"ok": False, "error": "Unauthorized"}), 401

        data = request.get_json(force=True) or {}
        phase_id = _clean_focus_phase_id(data.get("phase_id") or data.get("phaseId"))
        mode = (data.get("mode") or "pomodoro").strip()[:40] or "pomodoro"
        try:
            expected_minutes = int(data.get("expected_minutes") or data.get("minutes") or 0)
        except (TypeError, ValueError):
            expected_minutes = 0
        try:
            course_id = int(data.get("course_id") or data.get("courseId") or 0) or None
        except (TypeError, ValueError):
            course_id = None
        try:
            exam_id = int(data.get("exam_id") or data.get("examId") or 0) or None
        except (TypeError, ValueError):
            exam_id = None

        if not phase_id:
            return jsonify({"ok": False, "error": "Missing phase id"}), 400
        if expected_minutes < 0:
            expected_minutes = 0
        if expected_minutes > 480:
            expected_minutes = 480
        if not course_id:
            return jsonify({"ok": False, "error": "Pick a course before starting the timer."}), 400

        row = sdb.start_focus_phase(
            _cid(),
            phase_id=phase_id,
            mode=mode,
            expected_minutes=expected_minutes,
            course_id=course_id,
            exam_id=exam_id,
        )
        if not row:
            return jsonify({"ok": False, "error": "Could not verify focus phase"}), 400

        return jsonify({
            "ok": True,
            "phase_id": phase_id,
            "expected_minutes": int(row.get("expected_minutes") or expected_minutes or 0),
            "started_at": str(row.get("started_at") or ""),
        })


    @app.route("/api/student/focus/save", methods=["POST"])
    def student_save_focus():

        if not _logged_in():

            return jsonify({"error": "Unauthorized"}), 401

        data = request.get_json(force=True)

        cid = _cid()

        mode = data.get("mode", "pomodoro")

        try:
            minutes = int(data.get("minutes", 0))
        except (TypeError, ValueError):
            minutes = 0
        try:
            pages = int(data.get("pages", 0))
        except (TypeError, ValueError):
            pages = 0
        course_name = (data.get("course_name") or "").strip()
        # Optional structured tags — what the student is studying *for*
        # (course) and *which test* within that course (exam, optional).
        try:
            course_id = int(data.get("course_id") or 0) or None
        except (TypeError, ValueError):
            course_id = None
        try:
            exam_id = int(data.get("exam_id") or 0) or None
        except (TypeError, ValueError):
            exam_id = None
        phase_id = re.sub(r"[^A-Za-z0-9_.:-]", "", str(data.get("phase_id") or ""))[:80]

        # Backwards-compat: older clients still send only course_name. If we
        # have the name but not the id, look the id up so stats queries stay
        # exact (joins on course_id beat fragile note-string parsing).
        if course_name and not course_id:
            for _c in sdb.get_courses(cid):
                if _c["name"] == course_name:
                    course_id = int(_c["id"])
                    break

        # If course_id was resolved but the client didn't send a name, fill it
        # in from the DB so the `notes` string stays informative in the legacy
        # analytics widget that still reads it.
        if course_id and not course_name:
            for _c in sdb.get_courses(cid):
                if int(_c["id"]) == course_id:
                    course_name = _c["name"] or ""
                    break

        # Course is mandatory — "general study" was retired.
        if not course_name:
            return jsonify({"ok": False, "error": "Pick a course before starting the timer."}), 400

        # Defensive caps (real customers reported phantom hours from stale
        # localStorage / abandoned timers). Anything above 8h in a single save
        # is almost certainly a bug, not a real study session.
        if minutes < 0:
            return jsonify({"ok": False, "error": "Invalid minutes"}), 400
        if pages < 0:
            pages = 0
        if minutes > 480:
            minutes = 480

        # Drop empty saves entirely so we don't pollute the day.
        if minutes <= 0 and pages <= 0:
            return jsonify({"ok": True, "saved": False, "reason": "empty"})

        if phase_id:
            try:
                with sdb.get_db() as db:
                    already = sdb._fetchval(
                        db,
                        "SELECT id FROM student_xp WHERE client_id = %s AND action = 'focus_session' AND detail LIKE %s LIMIT 1",
                        (cid, f"%phase:{phase_id}%"),
                    )
                if already:
                    local_date = (request.args.get("local_date") or "").strip() or None
                    return jsonify({
                        "ok": True,
                        "saved": False,
                        "reason": "duplicate-phase",
                        "stats": sdb.get_focus_stats_today(cid, local_date=local_date),
                        "minutes_saved": 0,
                        "xp_awarded": 0,
                    })
            except Exception:
                pass

        atomic_claim = None
        if minutes > 0:
            if not phase_id:
                return jsonify({"ok": False, "error": "Unverified focus phase", "reason": "missing-phase-id"}), 400
            atomic_claim = sdb.claim_focus_phase_rewards(
                cid,
                phase_id,
                minutes=minutes,
                pages=pages,
                mode=mode,
                course_name=course_name,
                course_id=course_id,
                exam_id=exam_id,
            )
            if not atomic_claim.get("saved"):
                reason = atomic_claim.get("reason") or "server-error"
                if atomic_claim.get("ok"):
                    local_date = (request.args.get("local_date") or "").strip() or None
                    return jsonify({
                        "ok": True,
                        "saved": False,
                        "reason": reason,
                        "stats": sdb.get_focus_stats_today(cid, local_date=local_date),
                        "minutes_saved": 0,
                        "xp_awarded": 0,
                    })
                return jsonify({"ok": False, "error": "Unverified focus phase", "reason": reason}), 400

        # save_focus_session itself will further clamp by per-day total and
        # may return 0 if the day is already maxed out.
        if atomic_claim:
            saved_id = atomic_claim["session_id"]
            minutes_saved = int(atomic_claim.get("minutes_saved") or 0)
            pages_saved = int(atomic_claim.get("pages_saved") or 0)
        else:
            saved_id = sdb.save_focus_session(
                cid, mode=mode, minutes=minutes, pages=pages,
                course_name=course_name, course_id=course_id, exam_id=exam_id,
            )
            if not saved_id:
                return jsonify({"ok": True, "saved": False, "reason": "daily-cap-or-empty"})

            saved_row = sdb.get_focus_session_entry(saved_id, cid) or {}
            try:
                minutes_saved = int(saved_row.get("focus_minutes") or minutes or 0)
            except (TypeError, ValueError):
                minutes_saved = minutes
            try:
                pages_saved = int(saved_row.get("pages_read") or pages or 0)
            except (TypeError, ValueError):
                pages_saved = pages



        # Daily-quest progress (focus minutes + sessions + pages)

        if not atomic_claim:
            try:
                if minutes_saved > 0:
                    sdb.progress_quests_by_metric(cid, "focus_minutes", minutes_saved)
                    sdb.progress_quests_by_metric(cid, "sessions_completed", 1)
                if pages_saved > 0:
                    sdb.progress_quests_by_metric(cid, "pages_read", pages_saved)
            except Exception:
                pass



        # Focus is the primary reward source: 5 XP + 1 coin per 10 minutes.
        # Daily missions can add small XP bonuses, but quizzes and flashcards
        # remain study tools, not faucets.
        # Breaks aren't counted — `minutes` arrives study-only because the
        # frontend reports phaseWorkMinutes=0 for break phases.
        _focus_xp_awarded = int((atomic_claim or {}).get("xp_awarded") or 0)
        _focus_coins_awarded = int((atomic_claim or {}).get("coins_awarded") or 0)

        if minutes_saved > 0 and not atomic_claim:

            xp = (minutes_saved * 5) // 10  # 25 min -> 12 XP, 50 min -> 25 XP
            coins = minutes_saved // 10

            detail = f"{mode.title()} {minutes_saved}min"

            if course_name:

                detail += f" — {course_name}"

            if phase_id:

                detail += f" · phase:{phase_id}"

            if xp > 0:

                sdb.award_xp(cid, "focus_session", xp, detail)

                _focus_xp_awarded = xp
            if coins > 0:
                sdb.add_coins(cid, coins, f"focus_session {minutes_saved}min")
                _focus_coins_awarded = coins
            elif phase_id:

                # 0-XP micro phases still need a marker so phase-id dedupe
                # works on retries/refreshes. This does not affect total XP.
                sdb.award_xp(cid, "focus_session", 0, detail)

            if phase_id:
                try:
                    sdb.mark_focus_phase_claimed(cid, phase_id)
                except Exception:
                    pass


        # Auto-award focus badges

        stats = sdb.get_focus_stats(cid)

        total_hours = stats.get("total_hours", 0)

        if isinstance(total_hours, str):

            total_hours = float(total_hours.replace("h", "").replace(",", ""))

        else:

            total_hours = float(total_hours)

        if total_hours >= 1:

            sdb.earn_badge(cid, "focus_1h")

        if total_hours >= 10:

            sdb.earn_badge(cid, "focus_10h")

        if total_hours >= 50:

            sdb.earn_badge(cid, "focus_50h")

        if total_hours >= 100:

            sdb.earn_badge(cid, "focus_100h")

        total_pages = stats.get("total_pages", 0)

        if isinstance(total_pages, str):

            total_pages = int(total_pages)

        if total_pages >= 100:

            sdb.earn_badge(cid, "page_100")

        if total_pages >= 500:

            sdb.earn_badge(cid, "page_500")

        if total_pages >= 1000:

            sdb.earn_badge(cid, "page_1000")



        # Early bird / Night owl badges based on current time

        from datetime import datetime

        hour_now = datetime.now().hour

        if minutes_saved > 0:

            if hour_now < 7:

                sdb.earn_badge(cid, "early_bird")

            if hour_now >= 23:

                sdb.earn_badge(cid, "night_owl")

        # Centralized threshold + event/calendar/daily-XP badges.
        try:
            sdb.evaluate_badges(cid, stats=stats)
            if minutes_saved > 0:
                sdb.evaluate_event_badges(cid, session_minutes=minutes_saved)
        except Exception:
            pass

        # Promotion / demotion toasts intentionally disabled.
        # Leagues are XP-monotonic (no demotions) and the celebration toast
        # was distracting. Keep the response key for client back-compat.
        promotion = None



        # Frontend cards say "Horas hoy" / "Sesiones hoy" — return
        # today-scoped stats, not lifetime totals (lifetime `stats` above is
        # only used for badge thresholds).
        local_date = (request.args.get("local_date") or "").strip() or None
        today_stats = sdb.get_focus_stats_today(cid, local_date=local_date)

        return jsonify({
            "ok": True,
            "saved": True,
            "session_id": saved_id,
            "minutes_saved": minutes_saved,
            "pages_saved": pages_saved,
            "xp_awarded": _focus_xp_awarded,
            "coins_awarded": _focus_coins_awarded,
            "stats": today_stats,
            "promotion": promotion,
        })


    @app.route("/api/student/focus/claim-adjust", methods=["POST"])
    def student_focus_claim_adjust():
        if not _logged_in():
            return jsonify({"error": "Unauthorized"}), 401
        return jsonify({
            "ok": False,
            "error": "Focus claim adjustments are disabled. Claim registered phases instead.",
        }), 410


    @app.route("/api/student/focus/claim", methods=["POST"])
    def student_focus_claim_batch():
        """Claim all pending focus phases in one recoverable request.

        The old browser flow sent one request per phase. If the long-break claim
        had four phases and one request failed, the UI kept the user trapped in
        "retry claim" until a reload. This endpoint treats duplicate phase ids
        as already claimed and non-retryable skips as handled, so a refresh or a
        repeated click cannot double-credit or soft-lock the session.
        """

        if not _logged_in():
            return jsonify({"ok": False, "error": "Unauthorized"}), 401

        data = request.get_json(force=True) or {}
        phases = data.get("phases") or []
        if not isinstance(phases, list):
            phases = []
        phases = phases[:16]

        cid = _cid()
        local_date = (request.args.get("local_date") or "").strip() or None
        courses_cache = None
        fallback_course_name = (data.get("course_name") or data.get("fallback_course_name") or "").strip()
        try:
            fallback_course_id = int(data.get("course_id") or data.get("fallback_course_id") or 0) or None
        except (TypeError, ValueError):
            fallback_course_id = None
        try:
            fallback_exam_id = int(data.get("exam_id") or data.get("fallback_exam_id") or 0) or None
        except (TypeError, ValueError):
            fallback_exam_id = None

        def _clean_phase_id(raw) -> str:
            return re.sub(r"[^A-Za-z0-9_.:-]", "", str(raw or ""))[:80]

        def _resolve_course(course_name: str, course_id):
            nonlocal courses_cache
            try:
                resolved_id = int(course_id or 0) or None
            except (TypeError, ValueError):
                resolved_id = None
            resolved_name = (course_name or "").strip()
            if courses_cache is None:
                courses_cache = sdb.get_courses(cid) or []
            if resolved_id and not resolved_name:
                for c in courses_cache:
                    if int(c.get("id") or 0) == resolved_id:
                        resolved_name = c.get("name") or ""
                        break
            if resolved_name and not resolved_id:
                for c in courses_cache:
                    if (c.get("name") or "") == resolved_name:
                        resolved_id = int(c.get("id") or 0)
                        break
            return resolved_name, resolved_id

        saved_count = 0
        duplicate_count = 0
        skipped_count = 0
        failed_count = 0
        minutes_saved = 0
        xp_awarded = 0
        coins_awarded = 0
        results = []

        for idx, raw in enumerate(phases):
            if not isinstance(raw, dict):
                skipped_count += 1
                results.append({"index": idx, "ok": True, "saved": False, "reason": "invalid-phase"})
                continue

            try:
                minutes = int(raw.get("minutes") or 0)
            except (TypeError, ValueError):
                minutes = 0
            if minutes < 0:
                minutes = 0
            if minutes > 480:
                minutes = 480
            if minutes <= 0:
                skipped_count += 1
                results.append({"index": idx, "ok": True, "saved": False, "reason": "empty"})
                continue

            mode = (raw.get("mode") or "pomodoro").strip() or "pomodoro"
            phase_id = _clean_phase_id(raw.get("phaseId") or raw.get("phase_id"))
            course_name, course_id = _resolve_course(raw.get("courseName") or raw.get("course_name") or "", raw.get("courseId") or raw.get("course_id"))
            try:
                exam_id = int(raw.get("examId") or raw.get("exam_id") or 0) or None
            except (TypeError, ValueError):
                exam_id = None

            if not course_name:
                course_name, course_id = _resolve_course(fallback_course_name, fallback_course_id)
                if not exam_id:
                    exam_id = fallback_exam_id
            if not course_name:
                skipped_count += 1
                results.append({"index": idx, "ok": True, "saved": False, "reason": "missing-course"})
                continue

            if not phase_id:
                skipped_count += 1
                results.append({"index": idx, "ok": True, "saved": False, "reason": "missing-phase-id"})
                continue

            if phase_id:
                try:
                    with sdb.get_db() as db:
                        already = sdb._fetchval(
                            db,
                            "SELECT id FROM student_xp WHERE client_id = %s AND action = 'focus_session' AND detail LIKE %s LIMIT 1",
                            (cid, f"%phase:{phase_id}%"),
                        )
                    if already:
                        duplicate_count += 1
                        saved_count += 1
                        minutes_saved += minutes
                        xp_awarded += (minutes * 5) // 10
                        results.append({"index": idx, "ok": True, "saved": False, "reason": "duplicate-phase"})
                        continue
                except Exception:
                    pass

            try:
                claim = sdb.claim_focus_phase_rewards(
                    cid,
                    phase_id,
                    mode=mode,
                    minutes=minutes,
                    pages=0,
                    course_name=course_name,
                    course_id=course_id,
                    exam_id=exam_id,
                )
                if not claim.get("saved"):
                    reason = claim.get("reason") or "server-error"
                    if reason == "duplicate-phase":
                        duplicate_count += 1
                        saved_count += 1
                        minutes_saved += minutes
                        xp_awarded += (minutes * 5) // 10
                        results.append({"index": idx, "ok": True, "saved": False, "reason": reason})
                        continue
                    skipped_count += 1
                    results.append({"index": idx, "ok": bool(claim.get("ok")), "saved": False, "reason": reason})
                    continue

                saved_id = claim["session_id"]
                actual_minutes = int(claim.get("minutes_saved") or 0)
                int(claim.get("pages_saved") or 0)

                phase_xp = int(claim.get("xp_awarded") or 0)
                phase_coins = int(claim.get("coins_awarded") or 0)

                saved_count += 1
                minutes_saved += actual_minutes
                xp_awarded += phase_xp
                coins_awarded += phase_coins
                results.append({
                    "index": idx,
                    "ok": True,
                    "saved": True,
                    "session_id": saved_id,
                    "minutes_saved": actual_minutes,
                    "xp_awarded": phase_xp,
                    "coins_awarded": phase_coins,
                })
            except Exception as e:
                logging.getLogger("student.routes").exception("focus batch claim failed for client %s phase %s: %s", cid, idx, e)
                failed_count += 1
                results.append({"index": idx, "ok": False, "saved": False, "reason": "server-error"})

        try:
            stats = sdb.get_focus_stats(cid)
            total_hours = stats.get("total_hours", 0)
            if isinstance(total_hours, str):
                total_hours = float(total_hours.replace("h", "").replace(",", ""))
            else:
                total_hours = float(total_hours)
            if total_hours >= 1:
                sdb.earn_badge(cid, "focus_1h")
            if total_hours >= 10:
                sdb.earn_badge(cid, "focus_10h")
            if total_hours >= 50:
                sdb.earn_badge(cid, "focus_50h")
            if total_hours >= 100:
                sdb.earn_badge(cid, "focus_100h")
        except Exception:
            pass

        retryable = [phases[i] for i, r in enumerate(results) if not r.get("ok") and r.get("reason") == "server-error" and i < len(phases)]
        return jsonify({
            "ok": failed_count == 0,
            "saved": saved_count > 0,
            "saved_count": saved_count,
            "duplicate_count": duplicate_count,
            "skipped_count": skipped_count,
            "failed_count": failed_count,
            "minutes_saved": minutes_saved,
            "xp_awarded": xp_awarded,
            "coins_awarded": coins_awarded,
            "results": results,
            "retryable_phases": retryable,
            "stats": sdb.get_focus_stats_today(cid, local_date=local_date),
        }), (200 if failed_count == 0 or saved_count > 0 or skipped_count > 0 else 500)



