    @app.route("/api/student/flashcards/progress", methods=["POST"])

    def student_flashcard_progress():

        if not _logged_in():

            return jsonify({"error": "Unauthorized"}), 401

        data = request.get_json(force=True)

        quality = data.get("quality")  # 0-5 for SRS mode

        correct = data.get("correct", False)

        if quality is not None:

            quality = max(0, min(5, int(quality)))

            correct = quality >= 3

        cid = _cid()
        if not sdb.update_flashcard_progress(
            data["card_id"], cid, correct, quality=quality
        ):
            return jsonify({"error": "Not found"}), 404

        # Flashcards are practice only. Focus is the only XP/coin source.

        # Check flashcard badges

        from machreach_core.db import _fetchval, get_db

        with get_db() as db:

            fc_count = _fetchval(
                db,
                "SELECT COUNT(*) FROM student_flashcards f "
                "JOIN student_flashcard_decks d ON d.id = f.deck_id "
                "WHERE d.client_id = %s AND COALESCE(f.times_correct, 0) > 0",
                (cid,),
            ) or 0

        for key, threshold in [("flashcard_fan", 100), ("flashcard_500", 500), ("flashcard_1000", 1000)]:

            if fc_count >= threshold:

                sdb.earn_badge(cid, key)

        return jsonify({"ok": True})



