    def _quiz_job_status(client_id: int) -> dict:
        from machreach_core.db import get_async_job_status
        return get_async_job_status("student_quiz_generation", str(client_id), {"status": "idle"})


    def _set_quiz_job_status(client_id: int, status: str, progress: str = "", **payload) -> dict:
        from machreach_core.db import set_async_job_status
        error = str(payload.pop("error", "") or "")
        set_async_job_status(
            "student_quiz_generation",
            str(client_id),
            status,
            progress=progress,
            payload=payload,
            error=error,
        )
        return _quiz_job_status(client_id)


    def _queue_quiz_job(client_id: int, data: dict) -> dict:
        from machreach_core.db import enqueue_async_job
        return enqueue_async_job(
            "student_quiz_generation",
            str(client_id),
            input_payload=data,
            progress="Queued for quiz generation.",
        )


    @app.route("/api/student/quizzes/generate", methods=["POST"])
    @limiter.limit("5 per minute")

    def student_generate_quiz():

        """Generate AI quiz for a course."""

        if not _logged_in():

            return jsonify({"error": "Unauthorized"}), 401

        return jsonify({
            "error": "Synchronous quiz generation has been retired.",
            "replacement": "/api/student/quizzes/generate-async",
        }), 410

    @app.route("/api/student/quizzes/generate-async", methods=["POST"])
    @limiter.limit("5 per minute")

    def student_generate_quiz_async():

        """Start quiz generation in the background so long AI calls do not time out the browser."""

        if not _logged_in():

            return jsonify({"error": "Unauthorized"}), 401

        client_id = _cid()

        from student import subscription as _sub
        _ok, _why = _sub.can_generate_quiz_today(client_id)
        if not _ok:
            return jsonify({"error": _why, "upgrade_required": True}), 402

        existing = _quiz_job_status(client_id)
        if existing.get("status") in ("queued", "running"):
            return jsonify({"queued": True, "quiz_status": existing})

        data = request.get_json(force=True) if request.is_json else {}
        queued_status = _queue_quiz_job(client_id, data)

        return jsonify({"queued": True, "quiz_status": queued_status})


