    @app.route("/api/student/quizzes/<int:quiz_id>/score", methods=["POST"])
    def student_submit_quiz_score(quiz_id):

        if not _logged_in():

            return jsonify({"error": "Unauthorized"}), 401

        cid = _cid()
        if not sdb.get_quiz(quiz_id, cid):
            return jsonify({"error": "Not found"}), 404

        data = request.get_json(force=True) or {}
        submitted = data.get("answers") or []
        if not isinstance(submitted, list) or not submitted:
            return jsonify({"error": "Answers are required"}), 400

        questions = sdb.get_quiz_questions(quiz_id)
        if not questions:
            return jsonify({"error": "Quiz has no questions"}), 409
        expected = {int(q["id"]): str(q.get("correct") or "").lower() for q in questions}
        selected_by_id = {}
        for answer in submitted:
            try:
                question_id = int((answer or {}).get("q_id"))
            except (TypeError, ValueError):
                continue
            if question_id in expected and question_id not in selected_by_id:
                selected_by_id[question_id] = str((answer or {}).get("selected") or "").lower()
        correct_count = sum(
            1 for question_id, correct in expected.items()
            if selected_by_id.get(question_id) == correct
        )
        score = round(correct_count / len(expected) * 100)

        sdb.update_quiz_score(quiz_id, cid, score)

        # Quizzes are practice only. Focus is the only XP/coin source.

        if score == 100:

            sdb.earn_badge(cid, "quiz_master")

        if score == 77:

            sdb.earn_badge(cid, "lucky_seven")

        if not sdb.get_badges(cid) or not any(b["badge_key"] == "first_quiz" for b in sdb.get_badges(cid)):

            sdb.earn_badge(cid, "first_quiz")

        # Check quiz_10 badge

        from machreach_core.db import _fetchval, get_db

        with get_db() as db:

            quiz_count = _fetchval(db, "SELECT COUNT(*) FROM student_quizzes WHERE client_id = %s AND attempts > 0", (cid,)) or 0

        if quiz_count >= 10:

            sdb.earn_badge(cid, "quiz_10")

        if quiz_count >= 25:

            sdb.earn_badge(cid, "quiz_25")

        if quiz_count >= 50:

            sdb.earn_badge(cid, "quiz_50")

        try:
            sdb.evaluate_badges(cid)
        except Exception:
            pass

        return jsonify({"ok": True, "score": score, "correct": correct_count,
                        "total": len(expected)})



