    @app.route("/api/student/wallet/buy-coin-pack", methods=["POST"])
    def student_wallet_buy_coin_pack_api():
        """Microtransaction: kick off a Lemon Squeezy hosted-checkout for a
        coin pack. The actual credit happens server-side in the LS webhook
        (`order_created`), not here. Returns a `checkout_url` for the client
        to redirect to.
        """
        if not _logged_in():
            return jsonify(ok=False, error="Login required"), 401
        data = request.get_json(silent=True) or {}
        pack_key = str(data.get("pack_key") or "")
        if pack_key not in sdb.COIN_PACKS:
            return jsonify(ok=False, error="Unknown coin pack"), 400
        from machreach_core import lemonsqueezy as ls
        from machreach_core import config as _cfg
        variant_map = {
            "small":  _cfg.LS_VARIANT_COIN_SMALL,
            "medium": _cfg.LS_VARIANT_COIN_MEDIUM,
            "large":  _cfg.LS_VARIANT_COIN_LARGE,
            "mega":   _cfg.LS_VARIANT_COIN_MEGA,
            "ultra":  _cfg.LS_VARIANT_COIN_ULTRA,
        }
        if _cfg.LEMON_SQUEEZY_TEST_MODE:
            variant_map = {
                "small":  _cfg.LS_TEST_VARIANT_COIN_SMALL,
                "medium": _cfg.LS_TEST_VARIANT_COIN_MEDIUM,
                "large":  _cfg.LS_TEST_VARIANT_COIN_LARGE,
                "mega":   _cfg.LS_TEST_VARIANT_COIN_MEGA,
                "ultra":  _cfg.LS_TEST_VARIANT_COIN_ULTRA,
            }
        variant = variant_map.get(pack_key, "")
        product_map = {
            "small": _cfg.LS_TEST_PRODUCT_COIN_SMALL if _cfg.LEMON_SQUEEZY_TEST_MODE else _cfg.LS_PRODUCT_COIN_SMALL,
            "medium": _cfg.LS_TEST_PRODUCT_COIN_MEDIUM if _cfg.LEMON_SQUEEZY_TEST_MODE else _cfg.LS_PRODUCT_COIN_MEDIUM,
            "large": _cfg.LS_TEST_PRODUCT_COIN_LARGE if _cfg.LEMON_SQUEEZY_TEST_MODE else _cfg.LS_PRODUCT_COIN_LARGE,
            "mega": _cfg.LS_TEST_PRODUCT_COIN_MEGA if _cfg.LEMON_SQUEEZY_TEST_MODE else _cfg.LS_PRODUCT_COIN_MEGA,
            "ultra": _cfg.LS_TEST_PRODUCT_COIN_ULTRA if _cfg.LEMON_SQUEEZY_TEST_MODE else _cfg.LS_PRODUCT_COIN_ULTRA,
        }
        if not product_map.get(pack_key) or not variant:
            return jsonify(ok=False, error="Coin pack not configured for checkout."), 503
        if not ls.is_configured(test_mode=_cfg.LEMON_SQUEEZY_TEST_MODE):
            return jsonify(
                ok=False,
                error="Los pagos no están disponibles porque la facturación no está configurada.",
            ), 503
        cid = _cid()
        try:
            url = ls.create_checkout(
                variant,
                custom_data={"purpose": "coin_pack", "pack_key": pack_key, "client_id": str(cid)},
                email=session.get("email") or None,
                redirect_url=request.url_root.rstrip("/") + "/student/shop?section=coins&bought=1",
                test_mode=_cfg.LEMON_SQUEEZY_TEST_MODE,
            )
        except Exception as e:
            return jsonify(ok=False, error=str(e)), 500
        return jsonify(ok=True, checkout_url=url)


