    @app.route("/api/student/subscription/change", methods=["POST"])
    def student_subscription_change_api():
        """Switch student tier.

        - tier=free  -> ask Lemon Squeezy to cancel renewal; its webhook controls access.
        - Existing paid subscription -> change its provider variant in place;
          its webhook controls access.
        - New paid subscription -> return a Lemon Squeezy hosted-checkout URL.
          New-subscription activation happens server-side in the LS webhook.
        """
        if not _logged_in():
            return jsonify(ok=False, error="Login required"), 401
        data = request.get_json(silent=True) or {}
        tier = str(data.get("tier") or "").strip().lower()
        try:
            from student import subscription as _sub
            if tier == "ultimate":
                return jsonify(ok=False, error="Plan no disponible"), 400
            if tier not in _sub.PLANS:
                return jsonify(ok=False, error="Unknown plan"), 400
            if _sub.PLANS.get(tier, {}).get("locked"):
                return jsonify(ok=False, error="Este plan todavía está bloqueado."), 403
            cid = _cid()
            sub = _sub.get_subscription_state(cid)
            sub_id = str(sub.get("ls_sub_id") or "").strip()
            local_paid_tier = str(sub.get("tier") or "free").lower()
            provider_status = str(sub.get("status") or "").lower()
            from machreach_core import config as _cfg
            if tier == "free":
                # Cancel the active LS subscription if we have its id stashed.
                try:
                    from machreach_core import lemonsqueezy as ls
                    if sub_id:
                        cancelled = (
                            ls.cancel_subscription(sub_id, test_mode=True)
                            if _cfg.LEMON_SQUEEZY_TEST_MODE
                            else ls.cancel_subscription(sub_id)
                        )
                        if not cancelled:
                            return jsonify(ok=False, error="No pudimos cancelar tu suscripcion. Intentalo de nuevo o contacta soporte."), 502
                    elif local_paid_tier == "plus":
                        return jsonify(ok=False, error="No encontramos la suscripcion de pago para cancelarla. Contacta soporte."), 409
                except Exception as e:
                    log.exception("Student subscription cancellation failed for client %s: %s", cid, e)
                    return jsonify(ok=False, error="No pudimos cancelar tu suscripcion. Intentalo de nuevo o contacta soporte."), 502
                return jsonify(
                    ok=True,
                    tier=_sub.get_tier(cid),
                    cancellation_pending=True,
                    message="La cancelación fue enviada. Plus seguirá activo hasta el fin del ciclo pagado.",
                )
            # Upgrade -> hosted checkout
            from machreach_core import lemonsqueezy as ls
            variant = (
                _cfg.LS_TEST_VARIANT_STUDENT_PLUS
                if _cfg.LEMON_SQUEEZY_TEST_MODE
                else _cfg.LS_VARIANT_STUDENT_PLUS
            )
            product = (
                _cfg.LS_TEST_PRODUCT_STUDENT_PLUS
                if _cfg.LEMON_SQUEEZY_TEST_MODE
                else _cfg.LS_PRODUCT_STUDENT_PLUS
            )
            paid_tiers = {"plus"}
            renewable_statuses = {"active", "on_trial", "trialing", "paused", "cancelled"}
            delinquent_statuses = {"past_due", "unpaid"}
            terminal_statuses = {"expired", "inactive"}
            if local_paid_tier in paid_tiers and not sub_id:
                return jsonify(
                    ok=False,
                    error="No encontramos el identificador de tu suscripcion. Contacta soporte antes de cambiar de plan.",
                ), 409
            if sub_id and local_paid_tier in paid_tiers:
                if tier == local_paid_tier and provider_status in {"active", "on_trial", "trialing"}:
                    return jsonify(ok=True, tier=tier, unchanged=True)
                if provider_status in delinquent_statuses:
                    return jsonify(
                        ok=False,
                        error="Tu suscripcion tiene un pago pendiente. Actualiza el medio de pago o contacta soporte.",
                    ), 409
                if provider_status in renewable_statuses:
                    if not product or not variant:
                        return jsonify(ok=False, error="Plan not configured for checkout."), 503
                    if not ls.is_configured(test_mode=_cfg.LEMON_SQUEEZY_TEST_MODE):
                        return jsonify(
                            ok=False,
                            error="Los pagos no están disponibles porque la facturación no está configurada.",
                        ), 503
                    updated = (
                        ls.update_subscription_variant(sub_id, variant, test_mode=True)
                        if _cfg.LEMON_SQUEEZY_TEST_MODE
                        else ls.update_subscription_variant(sub_id, variant)
                    )
                    if not updated:
                        return jsonify(
                            ok=False,
                            error="No pudimos cambiar tu plan. Intentalo de nuevo o contacta soporte.",
                        ), 502
                    return jsonify(
                        ok=True,
                        tier=_sub.get_tier(cid),
                        update_pending=True,
                        message="El cambio se aplicará cuando Lemon Squeezy lo confirme.",
                    )
                if provider_status not in terminal_statuses:
                    return jsonify(
                        ok=False,
                        error="No pudimos verificar el estado de tu suscripcion. Contacta soporte antes de cambiar de plan.",
                    ), 409

            if not product or not variant:
                return jsonify(ok=False, error="Plan not configured for checkout."), 503
            if not ls.is_configured(test_mode=_cfg.LEMON_SQUEEZY_TEST_MODE):
                return jsonify(
                    ok=False,
                    error="Los pagos no están disponibles porque la facturación no está configurada.",
                ), 503
            url = ls.create_checkout(
                variant,
                custom_data={"purpose": "student_sub", "tier": tier, "client_id": str(cid)},
                email=session.get("email") or None,
                redirect_url=request.url_root.rstrip("/") + "/student/shop?upgraded=1",
                test_mode=_cfg.LEMON_SQUEEZY_TEST_MODE,
            )
            return jsonify(ok=True, checkout_url=url)
        except Exception as e:
            return jsonify(ok=False, error=str(e)), 500


    @app.route("/api/student/subscription/reconcile", methods=["POST"])
    def student_subscription_reconcile_api():
        """Restore the local Plus state from the provider's email-scoped record."""
        if not _logged_in():
            return jsonify(ok=False, error="Login required"), 401
        from machreach_core import config as _cfg
        from machreach_core import lemonsqueezy as ls
        from machreach_core.db import get_client
        from student import subscription as _sub

        test_mode = bool(_cfg.LEMON_SQUEEZY_TEST_MODE)
        variant = (
            _cfg.LS_TEST_VARIANT_STUDENT_PLUS
            if test_mode else _cfg.LS_VARIANT_STUDENT_PLUS
        )
        product = (
            _cfg.LS_TEST_PRODUCT_STUDENT_PLUS
            if test_mode else _cfg.LS_PRODUCT_STUDENT_PLUS
        )
        store = (
            _cfg.LEMON_SQUEEZY_TEST_STORE_ID
            if test_mode else _cfg.LEMON_SQUEEZY_STORE_ID
        )
        if not store or not product or not variant or not ls.is_configured(test_mode=test_mode):
            return jsonify(
                ok=False,
                error="La restauración no está disponible porque la facturación no está configurada.",
            ), 503
        client = get_client(_cid()) or {}
        email = str(client.get("email") or "").strip().lower()
        try:
            subscriptions = ls.list_subscriptions_by_email(
                email, test_mode=test_mode
            )
        except Exception as exc:
            log.exception("Subscription reconciliation failed for client %s: %s", _cid(), exc)
            return jsonify(
                ok=False,
                error="No pudimos consultar el estado de compra. Inténtalo nuevamente.",
            ), 502
        matches = [
            row for row in subscriptions
            if str((row.get("attributes") or {}).get("store_id") or "") == str(store)
            and str((row.get("attributes") or {}).get("product_id") or "") == str(product)
            and str((row.get("attributes") or {}).get("variant_id") or "") == str(variant)
            and str((row.get("attributes") or {}).get("user_email") or "").strip().lower()
            == email
        ]
        status_priority = {
            "active": 0,
            "on_trial": 0,
            "trialing": 0,
            "past_due": 1,
            "unpaid": 1,
            "cancelled": 2,
            "canceled": 2,
            "paused": 3,
            "expired": 4,
            "inactive": 4,
        }
        match = min(
            matches,
            key=lambda row: status_priority.get(
                str((row.get("attributes") or {}).get("status") or "").lower(),
                5,
            ),
            default=None,
        )
        if not match:
            result = _sub.set_subscription_state(
                _cid(),
                tier="free",
                status="inactive",
                ls_sub_id="",
                ends_at="",
                renews_at="",
                update_payment_method_url="",
                customer_portal_url="",
            )
            return jsonify(
                ok=True,
                restored=False,
                provider_match=False,
                tier=result.get("tier"),
                status=result.get("status"),
                message="No hay una suscripción Plus vigente para esta cuenta.",
            )
        attributes = match.get("attributes") or {}
        urls = attributes.get("urls") or {}
        result = _sub.set_subscription_state(
            _cid(),
            tier="plus",
            status=str(attributes.get("status") or "inactive"),
            ls_sub_id=str(match.get("id") or ""),
            ends_at=str(attributes.get("ends_at") or ""),
            renews_at=str(attributes.get("renews_at") or ""),
            update_payment_method_url=str(urls.get("update_payment_method") or ""),
            customer_portal_url=str(urls.get("customer_portal") or ""),
        )
        return jsonify(
            ok=True,
            restored=True,
            tier=result.get("tier"),
            status=result.get("status"),
            message="Estado de compra reconciliado con Lemon Squeezy.",
        )


    log.info("Student routes registered.")
